import { Component, EventEmitter, Input, input, Output, ViewChild, OnInit, OnChanges, SimpleChanges } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MatMenuModule, MatMenuTrigger } from '@angular/material/menu';
import { MatRadioModule } from '@angular/material/radio';
import { NgSelectModule } from '@ng-select/ng-select';
import { toolEvents } from '../../interfaces/pdf.interface';
import { CommonModule, NgIf } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'markoptions',
  standalone: true,
  imports: [MatRadioModule, FormsModule, MatMenuModule, NgSelectModule, CommonModule, TranslateModule],
  templateUrl: './markoptions.component.html',
  styleUrl: './markoptions.component.scss',
})
export class MarkoptionsComponent {
  @ViewChild(MatMenuTrigger) menuTrigger!: MatMenuTrigger;
  startPg: number = 1;
  endPg: number = 1;
  fileMode: any = 'F';
  CurruntSelected = 'C';
  @Output() linkEvent = new EventEmitter<toolEvents>();
  @Input() rangeList: any[] = [];

  // Filtered range list for end page dropdown
  endRangeList: any[] = [];

  OnPageModeChange(ev) { }

  OnPageSelected(flag) {
    if (flag === 'S') {
      // When start page is selected, filter the end range list
      this.updateEndRangeList();
    }
  }

  private updateEndRangeList() {
    // console.log('step-11 called')
    if (this.rangeList && this.rangeList.length > 0) {
      //filter to show only page affter select startpage
      this.endRangeList = this.rangeList.filter(
        (item) => item.page > this.startPg
      );
      // console.log('step-12', this.endRangeList);

      if (this.endRangeList.length === 0) {
        this.endPg = this.startPg;
      } else if (this.endPg <= this.startPg) {
        this.endPg = this.endRangeList[this.endRangeList.length - 1].page;
      }
    }
  }

  ngOnInit() {
    // console.log('step-1 called');
    // initialize end range list
    this.updateEndRangeList();
  }

  ngOnChanges(changes: SimpleChanges) {
    // console.log('step-4', changes);
    // when rangeList inpt chnge, update the end rangeList
    if (changes['rangeList'] && this.rangeList) {
      // console.log('step-5', this.rangeList);
      this.updateEndRangeList();
    }
  }

  open(flag) {
    (document.activeElement as HTMLElement).blur();
    if (this.CurruntSelected == 'D') {
      this.startPg = 1;
      this.endPg = this.rangeList.length ? this.rangeList[this.rangeList.length - 1].page : 1;
    }
    this.linkEvent.emit({ event: 'LINK-EVENT', data: { mode: this.fileMode, linkMode: flag, selectedMode: this.CurruntSelected, start: this.startPg, end: this.endPg } });
  }

  //  submit(btn) {
  //   (document.activeElement as HTMLElement).blur();
  //   this.linkEvent.emit({ event: 'LINK-EVENT', data: { mode: this.fileMode, linkMode: this.linkMode, start: this.startPg, end: this.endPg } });
  // }

  select(flag) {
    this.CurruntSelected = flag;
  }
}
