import { Directive, Input, OnDestroy, ChangeDetectorRef } from '@angular/core';
import { Subject } from 'rxjs';
import { DocInfo } from '../interfaces/pdf.interface';

/**
 * Abstract Base Class for PDF Tool Components.
 *
 * @description
 * Provides common functionality for all tool components in the PDF viewer:
 * - Shared Inputs: `nCaseid`, `docInfo`.
 * - Lifecycle Management: `destroy$` Subject for RxJS teardown.
 * - Performance: `ChangeDetectorRef` helper.
 *
 * @usageNotes
 * Extend this class for any component that lives inside the PDF Tool/Toolbar ecosystem.
 * Use `takeUntil(this.destroy$)` in subscriptions.
 */
@Directive()
export abstract class BasePdfToolComponent implements OnDestroy {

    /** Case Identifier ID */
    @Input() nCaseid: string = '';

    /** Document Information Object */
    @Input() docInfo: DocInfo | null = null;

    /**
     * Subject that emits when the component is destroyed.
     * Use with `takeUntil(this.destroy$)` to prevent memory leaks.
     */
    protected destroy$ = new Subject<void>();

    constructor(protected cdr: ChangeDetectorRef) { }

    /**
     * Cleanup lifecycle hook.
     * Completes the destroy$ subject.
     */
    ngOnDestroy(): void {
        this.destroy$.next();
        this.destroy$.complete();
    }

    /**
     * Helper to manually mark component for check.
     * Use when OnPush strategy doesn't auto-detect a change (e.g. async logic).
     */
    protected markForCheck(): void {
        this.cdr.markForCheck();
    }

    /**
     * Safe string conversion helper.
     * @param val Any value
     * @returns String representation
     */
    protected convToStr(val: any): string {
        return val ? JSON.stringify(val) : '';
    }
}
