import { ChangeDetectionStrategy, ChangeDetectorRef, Component, ElementRef, EventEmitter, Input, OnChanges, OnInit, Output, SimpleChanges, ViewChild } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { toolEvents } from '../../interfaces/pdf.interface';
import { PdfSharedModule } from '../../modules/shared/shared.module';
import { ButtonComponent } from '../../../shared/components/button/button.component';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { IconComponent } from '../../../shared/components/icon/icon.component';
import { CommonModule } from '@angular/common';
import { advanceFiler, elasticPages } from '../../../userpanel/interfaces/advance-search.interface';
import { MatMenuModule } from '@angular/material/menu';
import { AdvanceSearchService } from '../../../userpanel/services/advance-search/advance-search.service';
import { CommunicationService } from '../../../shared/services/communication/communication.service';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';

@Component({
  selector: 'pdfsearch',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [PdfSharedModule, FormsModule, ButtonComponent, MatCheckboxModule, IconComponent, CommonModule, MatMenuModule],
  templateUrl: './search.component.html',
  styleUrl: './search.component.scss'
})
export class SearchComponent implements OnInit, OnChanges {
  @Input() cSearch: string = '';
  @Input() cSearchChange: EventEmitter<string>;
  @Input() matchCase: boolean = false;
  @Input() wholeWords: boolean = false;
  @Input() totalSearch: number = 0;
  @Input() totalElasticMaches: number = 0;
  @Input() currentSearch: number = 0;
  @Input() isSearching: boolean = false;
  @Input() isfullmode: boolean = false;
  @Output() searchEvents = new EventEmitter<toolEvents>();
  @Output() ValueUpdate = new EventEmitter<toolEvents>();
  searching_value: string = '';
  @Input() jFilter: advanceFiler | null = null;
  @Output() jFilterChange = new EventEmitter<advanceFiler>();
  @Input() isElasticSearched: boolean = false;
  @Output() isElasticSearchedChange = new EventEmitter<boolean>();
  @Input() elasticPages: elasticPages[] = [];
  @Input() searchPageIndex: number = 0;
  @Input() pdfLoaded: boolean = false;

  @ViewChild('searchInput') searchInput!: ElementRef<HTMLInputElement>;

  constructor(private cdr: ChangeDetectorRef, private advancesearchService: AdvanceSearchService,
    private cs: CommunicationService
  ) {
    this.cs.functionCalled$
      .pipe(takeUntilDestroyed())
      .subscribe(async (data) => {
        if (data === 'CLEAR-PDF-SEARCH') {
          this.clearSearch();
        }
      });
  }


  find() {

    this.OnKeyUp(null);
    this.cSearchChange?.emit(this.cSearch);
    if (this.searching_value == this.cSearch) {
      this.findNext();
      return
    }
    this.searching_value = this.cSearch;
    this.cdr.markForCheck();
    this.searchEvents.next({ event: 'SEARCH', data: { cSearch: this.cSearch, options: { matchCase: this.matchCase, wholeWords: this.wholeWords, highlightAll: true } } });
  }

  findPrevious() {
    this.searchEvents.next({ event: 'SEARCH_PREVIOUS', data: { cSearch: this.cSearch, options: { matchCase: this.matchCase, wholeWords: this.wholeWords, highlightAll: true } } });
  }

  findNext() {
    this.searchEvents.next({ event: 'SEARCH_NEXT', data: { cSearch: this.cSearch, options: { matchCase: this.matchCase, wholeWords: this.wholeWords, highlightAll: true } } });
  }
  OnKeyUp(e: KeyboardEvent | null) {
    if (e) {
      this.removeElasticSearch()
    }
    this.ValueUpdate.next({ event: 'VALUE_UPDATE', data: { cSearch: this.cSearch, options: { matchCase: this.matchCase, wholeWords: this.wholeWords, highlightAll: true } } });
  }

  ngOnInit(): void {
    setTimeout(() => {
      if (this.searchInput) {
        this.searchInput.nativeElement.focus();
      }
    }, 100);

    if (this.cSearch) {
      if (this.pdfLoaded) {
        this.find();
      }
    }


  }
  ngOnChanges(changes: SimpleChanges): void {
    if (changes["totalSearch"]) {
      this.cdr.markForCheck();
    }
    if (changes["isSearching"]) {
      this.cdr.markForCheck();
    }

    if (changes['pdfLoaded']) {
      this.pdfLoaded = changes['pdfLoaded'].currentValue;
      if (this.pdfLoaded) {
        this.find();
      }
      this.cdr.markForCheck()
    }
  }

  clearSearch() {
    this.cSearch = '';
    this.find();
    // this.close();
    this.isSearching = false;
    this.searching_value = '';
    this.totalSearch = 0;
    this.currentSearch = 0;
    if (this.searchInput) {
      this.searchInput.nativeElement.focus();
    }
    this.cdr.markForCheck();
  }

  close() {
    let close: toolEvents = { event: 'close', data: null };
    this.searchEvents.next(close);

  }


  goToPage(x: elasticPages, i: number) {
    this.searchPageIndex = i;
    this.searchEvents.next({ event: 'SEARCH-PAGE-REDIRECT', data: { page: Number(x.page) } });
    this.cdr.markForCheck();
  }


  redirectPage(val: number) {
    const newPg: elasticPages = this.elasticPages[(this.searchPageIndex) + val];
    if (newPg) {
      this.goToPage(newPg, (this.searchPageIndex) + val);
    }
  }

  onKeydown(e: KeyboardEvent) {
    if (e.key === 'Enter') {
      const target = e.target as HTMLInputElement;
      this.searchPageIndex = (Number(target.value) || 1) - 1;
      const onj = this.elasticPages[this.searchPageIndex];
      if (onj) {
        const enteredValue = Number(onj?.page);
        const closestPage = this.elasticPages.reduce((prev, curr) => {
          return (Math.abs(curr.page - enteredValue) < Math.abs(prev.page - enteredValue) ? curr : prev);
        });
        this.goToPage(closestPage, this.searchPageIndex);
      }
    }
  }

  removeElasticSearch() {
    this.jFilter = null;
    this.isElasticSearched = false;
    this.elasticPages = [];
    this.searchPageIndex = 0;
    this.isElasticSearchedChange.emit(this.isElasticSearched);
    this.jFilterChange.emit(this.jFilter!);
    this.cdr.markForCheck();
  }

}