import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, OnInit, Output, ViewChild } from '@angular/core';
import { CommonModule } from '@angular/common';
import { MatMenuModule } from '@angular/material/menu';
import { MatButtonModule } from '@angular/material/button';
import { MatTooltipModule } from '@angular/material/tooltip';
import { TranslateModule } from '@ngx-translate/core';
import { NgScrollbarModule } from 'ngx-scrollbar';

import { IconComponent } from '../../../shared/components/icon/icon.component';
import { ChooseIssueComponent } from '../../../shared/components/issues/choose-issue/choose-issue.component';
import { ToolboxComponent } from '../toolbox/toolbox.component';
import { BasePdfToolComponent } from '../../base/base-pdf-tool.component';
import { highlightModeType, highlightToolType, temporaryAnnots } from '../../interfaces/pdf.interface';
import { selectedIssues as SelectedIssue } from '../../../shared/interfaces/issue.interface';
import { ToolIcon, ToolBoxEvent, TOOL_ICONS, NO_ICON, DEFAULT_ANNOT_TOOL_MODE, DEFAULT_HIGHLIGHT_MODE, TOOL_EVENTS } from '../../interfaces/annot-tools.interface';

/**
 * Annotation Tools Component.
 *
 * @description
 * Container for the left-side annotation toolbar (Highlighter, Pencil, Shape, etc.).
 * Manages tool selection mode and communicates with the parent PDF component.
 *
 * @extends BasePdfToolComponent
 */
@Component({
  selector: 'annot-tools',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [
    CommonModule,
    IconComponent,
    MatTooltipModule,
    TranslateModule,
    MatMenuModule,
    MatButtonModule,
    NgScrollbarModule,
    ToolboxComponent,
    ChooseIssueComponent
  ],
  templateUrl: './annot-tools.component.html',
  styleUrl: './annot-tools.component.scss'
})
export class AnnotToolsComponent extends BasePdfToolComponent implements OnInit {

  @ViewChild('issuesComponent') issues!: ChooseIssueComponent;

  /** Emits when the annotation toolbar is closed */
  @Output() readonly OnClose = new EventEmitter<void>();

  /** Emits when the active tool mode changes (e.g. 'F', 'D') */
  @Output() readonly OnModeChange = new EventEmitter<highlightToolType>();

  /** Emits generic toolbox events (color change, issue change, etc.) */
  @Output() readonly OnToolBoxEvent = new EventEmitter<ToolBoxEvent>();

  /** Active annotation tool mode */
  @Input() annotToolMode: highlightToolType = DEFAULT_ANNOT_TOOL_MODE;

  /** List of selected issues associated with the current annotation */
  @Input() selectedIssues: SelectedIssue[] = [];

  /** Active highlight mode */
  @Input() highlightMode: highlightModeType = DEFAULT_HIGHLIGHT_MODE; // Default to Quick Fact

  /** Temporary annotations being drawn */
  public tempAnnots: temporaryAnnots[] = [];

  /** Selected Fact Sheet ID */
  public nFSid: string | null = null;

  /** Tool definitions */
  public readonly icons: ToolIcon[] = TOOL_ICONS;

  public readonly noIcon: ToolIcon = NO_ICON;

  constructor(cdr: ChangeDetectorRef) {
    super(cdr);
  }

  ngOnInit(): void {
    this.initializeTools();
  }

  /**
   * Initialize tool settings based on document mode.
   */
  private initializeTools(): void {
    // If in "Presentation" mode (nPresentid exists), add the Cursor tool
    if (this.docInfo?.nPresentid) {
      this.icons.unshift(this.noIcon);
    }
  }

  /**
   * Close the annotation toolbar.
   */
  public onAnnotClose(): void {
    this.OnClose.emit();
  }

  /**
   * Switch the active annotation tool type.
   * @param type The new tool type
   */
  public changeType(type: highlightToolType): void {
    this.annotToolMode = type;
    this.OnModeChange.emit(this.annotToolMode);
    this.markForCheck();
  }

  /**
   * Handle events from the sub-toolbox component.
   * @param e Event data
   */
  public onToolboxClick(e: ToolBoxEvent): void {
    if (!e) return;

    this.highlightMode = e.mode ?? this.highlightMode;
    this.OnToolBoxEvent.emit({ event: TOOL_EVENTS.ANNOT_TOOL_CHANGE, data: e.mode });

    const newMode = e.mode === 'QF' ? 'F' : (e.mode as any);
    this.OnModeChange.emit(newMode as highlightToolType);
  }

  /**
   * Handle events from the Issue Menu or generic toolbox actions.
   * @param e Event payload
   * @param menu Reference to the MatMenu to close it
   */
  public onEvent(e: ToolBoxEvent, menu: { closeMenu?: () => void } | null): void {
    if (e.event === TOOL_EVENTS.ISSUE_CHANGE) {
      this.selectedIssues = (e.data as SelectedIssue[]) ?? this.selectedIssues;
      this.markForCheck();
    }
    if (e.event === TOOL_EVENTS.ADVANCE) {
      if (menu && typeof menu.closeMenu === 'function') {
        menu.closeMenu();
      }
      this.OnToolBoxEvent.emit({ event: TOOL_EVENTS.ADVANCE, data: e.data });
    }
  }

  /**
   * Manually trigger issue component initialization.
   * @deprecated Should use OnChanges or declarative approach in issues component.
   */
  public loadIssue(): void {
    this.issues?.ngOnInit();
  }
}
